def eval_expr(s):
    tokens = tokenize(s)
    pos = [0]  # mutable index

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def consume(expected=None):
        t = tokens[pos[0]]
        if expected is not None and t != expected:
            raise ValueError(f"Expected '{expected}', got '{t}'")
        pos[0] += 1
        return t

    def parse_add_sub():
        left = parse_mul_div()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_mul_div()
            left = left + right if op == '+' else left - right
        return left

    def parse_mul_div():
        left = parse_unary()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_unary()
            if op == '*':
                left *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                left /= right
        return left

    def parse_unary():
        if peek() == '-':
            consume('-')
            return -parse_unary()
        if peek() == '+':
            consume('+')
            return parse_unary()
        return parse_primary()

    def parse_primary():
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of input")
        if t == '(':
            consume('(')
            val = parse_add_sub()
            consume(')')
            return val
        if t.isdigit():
            consume()
            return float(t)
        raise ValueError(f"Unexpected token: {t}")

    result = parse_add_sub()
    if pos[0] != len(tokens):
        raise ValueError(f"Unexpected token: {tokens[pos[0]]}")
    return result


def tokenize(s):
    tokens = []
    i = 0
    while i < len(s):
        c = s[i]
        if c.isspace():
            i += 1
        elif c in '+-*/()':
            tokens.append(c)
            i += 1
        elif c.isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            tokens.append(s[i:j])
            i = j
        else:
            raise ValueError(f"Invalid character: {c}")
    return tokens
