def topo_count(n, edges):
    in_mask = [0] * n
    for u, v in edges:
        in_mask[v] |= 1 << u

    dp = [0] * (1 << n)
    dp[0] = 1

    for mask in range(1 << n):
        if dp[mask] == 0:
            continue
        for i in range(n):
            if not (mask & (1 << i)) and (mask & in_mask[i]) == in_mask[i]:
                dp[mask | (1 << i)] += dp[mask]

    return dp[(1 << n) - 1]
